 q('#min-monitor-mode').dataset.minAction='monitor';q('#min-monitor-mode').onclick=()=>action('monitor',q('#min-monitor-mode'),()=>{monitor=!monitor;});q('#min-msf').onclick=()=>host.toast('msf RPC is unavailable in this sample.');q('#min-burp').onclick=()=>host.toast('Sample proxy: 127.0.0.1:8080. No browser traffic is routed.');for(const name of fixtures.tools)q('#min-kali-tools').append(button(name,()=>{open('minlauncher');q('#min-launch-search').value=name;drawLauncher();}));
 function clock(){const now=new Date(),time=now.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:false});q('#min-clock').textContent=time;q('#min-clock').setAttribute('datetime',now.toISOString());q('#min-date').textContent=now.toLocaleDateString('en-GB',{weekday:'short',day:'2-digit',month:'short'})+' '+time;}
 function spark(kind,values){const n=q('[data-min-spark='+kind+']'),max=kind==='cpu'?100:Math.max(1,...values)*1.2;n.setAttribute('points',values.map((v,i)=>(i/Math.max(1,values.length-1)*100)+','+(15-v/max*13)).join(' '));}
 function updateNetwork(value){net=value;sync(state);}
