  q('#min-battery').hidden=!state.hardware.battery;q('[data-min-battery-line]').hidden=!state.hardware.battery;if(state.hardware.battery){text('[data-min-battery]',state.hardware.battery.percent+'%');text('[data-min-battery-line]','bat '+state.hardware.battery.percent+'% · '+state.hardware.battery.watts+' W · '+state.hardware.battery.temperature+'°C');}
