  facts(q('#min-system-facts'),[['cpu temp','46°C · fan 1,200 rpm'],['battery',state.hardware.battery?state.hardware.battery.percent+'% · '+state.hardware.battery.watts+' W':'unavailable'],['health',state.hardware.battery?state.hardware.battery.health+'%':'—'],['disk io','3.9 MB/s'],['load','0.42'],['uptime','3 h 24 m']]);
