  for(const c of state.dev.containers){const n=q('[data-container='+c.id+']'),b=n.querySelector('button');n.querySelector('small').textContent=c.cpu.toFixed(1)+'% · '+c.memory+'M';const status=n.querySelector('.min-tag');status.textContent=c.state==='running'?'up':'exited';status.dataset.tone=c.state==='running'?'ok':'error';if(armed!=='container-'+c.id)b.textContent=c.state==='running'?'stop':'start';b.disabled=Boolean(pending);}
