 function configure({family,palette,effects}){const was=enabled;enabled=family==='minimalistix';ui.hidden=!enabled;mode=effects;variant=palette;setToken('popup',D.modes[mode].popup);text('#min-poll-label',D.modes[mode].poll+' s poll');if(enabled){q('#min-terminal-colours').replaceChildren(...D.palettes[variant].term.map(color=>{const n=create('span');n.style.backgroundColor=color;return n;}));syncWindows();sync(host.model.snapshot());}if(was!==enabled||enabled)schedule();if(!enabled){clearAction();clearTimeout(noticeTimer);q('#min-notification').hidden=true;}}
 function schedule(){clearTimeout(timer);timer=null;if(!enabled||document.hidden)return;stamp=Date.now();timer=setTimeout(()=>{timer=null;const elapsed=Math.max(.1,(Date.now()-stamp)/1000);host.model.tick(elapsed,{system:!host.inspectorOpen(),media:false});schedule();},D.modes[mode].poll*1000);}
