 function drawLauncher(){const term=q('#min-launch-search').value.trim().toLowerCase();launchItems=launcherRecords().filter(([name])=>name.toLowerCase().includes(term));launchIndex=Math.min(launchIndex,Math.max(0,launchItems.length-1));q('#min-launch-results').replaceChildren();launchItems.forEach(([name,kind,run],i)=>{const b=button('',()=>{host.close();run();});b.append(create('span',name),create('small',kind));b.setAttribute('role','option');b.id='min-launch-result-'+i;b.setAttribute('aria-selected',i===launchIndex);q('#min-launch-results').append(b);});if(launchItems.length)q('#min-launch-search').setAttribute('aria-activedescendant','min-launch-result-'+launchIndex);else q('#min-launch-search').removeAttribute('aria-activedescendant');if(!launchItems.length)q('#min-launch-results').append(create('p','No matching items. Try another mode.'));q('#min-launch-modes').replaceChildren(...['drun','run','window','power'].map(name=>{const b=button(name,()=>{launchMode=name;launchIndex=0;drawLauncher();q('#min-launch-search').focus();});b.setAttribute('aria-pressed',launchMode===name);return b;}));}
 q('#min-launch-search').oninput=()=>{launchIndex=0;drawLauncher();};q('#min-launch-search').addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp'].includes(e.key)&&launchItems.length){e.preventDefault();launchIndex=(launchIndex+(e.key==='ArrowDown'?1:-1)+launchItems.length)%launchItems.length;drawLauncher();}else if(e.key==='Enter'&&launchItems[launchIndex]){e.preventDefault();const run=launchItems[launchIndex][2];host.close();run();}});
