 const routes={'min-launch':()=>open('minlauncher'),'min-dock-launch':()=>open('minlauncher'),'min-overview':()=>{open('minlauncher');launchMode='window';drawLauncher();},'min-monitor':()=>open('hud'),'min-containers':()=>open('hud'),'min-devtools':()=>open('drawer'),'min-net':()=>host.network(),'min-wifi':()=>host.network(),'min-hud-wifi':()=>host.network(),'min-audio':()=>host.inspect('Audio'),'min-brightness':()=>host.inspect('Display'),'min-battery':()=>host.inspect('Display'),'min-playing':()=>host.inspect('Media'),'min-controls':()=>host.controls(),'min-notify':notify,'min-browser':()=>{open('minlauncher');q('#min-launch-search').value='Firefox';drawLauncher();},'min-updates':()=>host.toast('14 sample package updates · native package manager integration pending.')};for(const[id,fn]of Object.entries(routes))q('#'+id).onclick=fn;
 root.addEventListener('keydown',e=>{if(!enabled||e.defaultPrevented||e.ctrlKey||e.altKey||e.target.matches('input,textarea,select,[contenteditable]'))return;const key=e.key.toLowerCase();if((!overlay||['hud','drawer','minlauncher'].includes(overlay))&&['h','`',' ','n'].includes(key)){e.preventDefault();if(key==='h')open('hud',document.activeElement);if(key==='`')open('drawer',document.activeElement);if(key===' ')open('minlauncher',document.activeElement);if(key==='n')notify();}});
